{'code': "from qgis import utils
mm = utils.plugins.get('mmqgis')
res = {}
attrs = [a for a in dir(mm) if 'select' in a.lower() or 'search' in a.lower()]
res['attrs'] = attrs
for a_name in attrs:
    obj = getattr(mm, a_name)
    if a_name.endswith('_action'):
        res[a_name] = {'text': obj.text(), 'enabled': obj.isEnabled(), 'visible': obj.isVisible(),
                       'in_search_menu': obj in mm.search_select_menu.actions()}
    elif a_name != 'search_select_menu':
        res[a_name] = repr(obj)[:150]
result = res"}
